#!/usr/bin/env python3
import csv
import json
import sys
import os
import argparse

def csv_to_json(file_path, indent=None):
    """
    Reads a CSV file and returns a JSON string representing the rows as a list of objects.

    Args:
        file_path (str): Path to the CSV file.
        indent (int, optional): Indentation level for JSON pretty-printing.

    Returns:
        str: JSON string of the CSV data.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file is empty or has no headers.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    if os.path.getsize(file_path) == 0:
        raise ValueError(f"File is empty: {file_path}")

    rows = []
    try:
        with open(file_path, mode='r', encoding='utf-8', newline='') as csvfile:
            reader = csv.reader(csvfile)
            headers = next(reader, None)

            if headers is None:
                raise ValueError("CSV file is empty (no headers found).")

            for row in reader:
                if len(row) == len(headers):
                    rows.append(dict(zip(headers, row)))
                elif len(row) < len(headers):
                    padded_row = row + [''] * (len(headers) - len(row))
                    rows.append(dict(zip(headers, padded_row)))
                else:
                    rows.append(dict(zip(headers, row[:len(headers)])))

    except Exception as e:
        raise e

    return json.dumps(rows, indent=indent)

def main():
    parser = argparse.ArgumentParser(description="Convert a CSV file to JSON format.")
    parser.add_argument("file_path", help="Path to the CSV file")
    parser.add_argument("--indent", type=int, default=None, help="Indentation level for pretty-printing JSON output")

    args = parser.parse_args()

    try:
        json_str = csv_to_json(args.file_path, indent=args.indent)
        print(json_str)
    except (FileNotFoundError, ValueError) as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
